    if (A.is_cuda() == false) A = A.cuda();
    if (B.is_cuda() == false) B = B.cuda();

    auto M = A.size(0);
    auto K = A.size(1);
    auto N = B.size(1);
    auto C = torch::empty({M, N}, A.options());

    dim3 block_size(16, 16);
    dim3 num_blocks((N + 63) / 64, (M + 63) / 64);

    tall_skinny_matmul_v3_kernel<<<num_blocks, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

